 * The lexer. Turns UTF-8 source text into a flat array of tokens, or throws
 * a `LexError` carrying the line, column and reason of the first problem.
 */

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const TWO_CHAR_PUNCT = ['==', '!=', '<=', '>=', '&&', '||', '->', '=>']
const ONE_CHAR_PUNCT = new Set(['+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.'])

const isDecimalDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isHexDigit = (c) => c !== undefined && (isDecimalDigit(c) || (c >= 'a' && c <= 'f') || (c >= 'A' && c <= 'F'))
const isBinaryDigit = (c) => c === '0' || c === '1'
const isOctalDigit = (c) => c !== undefined && c >= '0' && c <= '7'
const isIdentStart = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c === '_')
const isIdentPart = (c) => c !== undefined && (isIdentStart(c) || isDecimalDigit(c))

class LexError extends Error {
  constructor(line, column, reason) {
    super(reason)
    this.line = line
    this.column = column
    this.reason = reason
  }
}

function hexValue(c) {
  if (c >= '0' && c <= '9') return c.charCodeAt(0) - 0x30
  if (c >= 'a' && c <= 'f') return c.charCodeAt(0) - 0x61 + 10
  return c.charCodeAt(0) - 0x41 + 10
}

/** Scans `source` into an array of `{ line, column, kind, text }` tokens. */
export function scan(source) {
  const chars = Array.from(source)
  let idx = 0
  let line = 1
  let column = 1

  function current() {
    return chars[idx]
  }

  function peekAt(offset) {
    return chars[idx + offset]
  }

  function advance() {
    const c = chars[idx]
    idx += 1
    if (c === '\n') {
      line += 1
      column = 1
    } else if (c === '\t') {
      column = Math.floor((column - 1) / 4) * 4 + 5
    } else {
      column += 1
    }
    return c
  }

  function fail(l, c, reason) {
    throw new LexError(l, c, reason)
  }

  // Consumes a run of digits (per `isDigit`), allowing a single `_` between
  // two digits of the run. Returns true if at least one digit was consumed.
  function scanDigitRun(isDigit) {
    if (!isDigit(current())) return false
    advance()
    while (true) {
      if (isDigit(current())) {
        advance()
      } else if (current() === '_' && isDigit(peekAt(1))) {
        advance()
        advance()
      } else {
        break
      }
    }
    return true
  }

  function skipTrivia() {
    while (true) {
      const c = current()
      if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
        advance()
        continue
      }
      if (c === '/' && peekAt(1) === '/') {
        advance()
        advance()
        while (current() !== undefined && current() !== '\n') advance()
        continue
      }
      if (c === '/' && peekAt(1) === '*') {
        const startLine = line
        const startColumn = column
        advance()
        advance()
        let depth = 1
        while (depth > 0) {
          if (current() === undefined) {
            fail(startLine, startColumn, 'unterminated block comment')
          } else if (current() === '/' && peekAt(1) === '*') {
            advance()
            advance()
            depth += 1
          } else if (current() === '*' && peekAt(1) === '/') {
            advance()
            advance()
            depth -= 1
          } else {
            advance()
          }
        }
        continue
      }
      break
    }
  }

  function scanNumber() {
    const startLine = line
    const startColumn = column
    const startIdx = idx
    let prefixWithNoDigit = false

    if (current() === '0' && (peekAt(1) === 'x' || peekAt(1) === 'X')) {
      advance()
      advance()
      if (!scanDigitRun(isHexDigit)) prefixWithNoDigit = true
    } else if (current() === '0' && (peekAt(1) === 'b' || peekAt(1) === 'B')) {
      advance()
      advance()
      if (!scanDigitRun(isBinaryDigit)) prefixWithNoDigit = true
    } else if (current() === '0' && (peekAt(1) === 'o' || peekAt(1) === 'O')) {
      advance()
      advance()
      if (!scanDigitRun(isOctalDigit)) prefixWithNoDigit = true
    } else {
      scanDigitRun(isDecimalDigit)
      if (current() === '.' && isDecimalDigit(peekAt(1))) {
        advance()
        scanDigitRun(isDecimalDigit)
      }
      if (current() === 'e' || current() === 'E') {
        const afterE = peekAt(1)
        const isSign = afterE === '+' || afterE === '-'
        const digitAfterE = isSign ? peekAt(2) : afterE
        if (isDecimalDigit(digitAfterE)) {
          advance()
          if (isSign) advance()
          scanDigitRun(isDecimalDigit)
        }
      }
    }

    let text = chars.slice(startIdx, idx).join('')

    if (isIdentPart(current())) {
      const trailStart = idx
      while (isIdentPart(current())) advance()
      text += chars.slice(trailStart, idx).join('')
      fail(startLine, startColumn, `invalid number ${text}`)
    }

    if (prefixWithNoDigit) {
      fail(startLine, startColumn, `invalid number ${text}`)
    }

    return { line: startLine, column: startColumn, kind: 'number', text }
  }

  function scanString() {
    const startLine = line
    const startColumn = column
    advance() // opening quote
    let decoded = ''
    while (true) {
      if (current() === undefined) fail(startLine, startColumn, 'unterminated string')
      if (current() === '"') {
        advance()
        break
      }
      if (current() === '\n') fail(line, column, 'newline in string')
      if (current() === '\\') {
        const backslashLine = line
        const backslashColumn = column
        advance() // backslash
        if (current() === undefined) fail(startLine, startColumn, 'unterminated string')
        const e = current()
        if (e === 'n') {
          decoded += '\n'
          advance()
        } else if (e === 't') {
          decoded += '\t'
          advance()
        } else if (e === 'r') {
          decoded += '\r'
          advance()
        } else if (e === '\\') {
          decoded += '\\'
          advance()
        } else if (e === '"') {
          decoded += '"'
          advance()
        } else if (e === '0') {
          decoded += '\0'
          advance()
        } else if (e === 'x') {
          advance()
          const h1 = current()
          const h2 = peekAt(1)
          if (isHexDigit(h1) && isHexDigit(h2)) {
            advance()
            advance()
            decoded += String.fromCharCode(hexValue(h1) * 16 + hexValue(h2))
          } else {
            fail(backslashLine, backslashColumn, 'invalid escape \\x')
          }
        } else if (e === 'u') {
          advance()
          if (current() !== '{') fail(backslashLine, backslashColumn, 'invalid escape \\u')
          advance()
          let digits = ''
          while (isHexDigit(current())) {
            digits += current()
            advance()
          }
          if (digits.length === 0 || current() !== '}') {
            fail(backslashLine, backslashColumn, 'invalid escape \\u')
          }
          const value = parseInt(digits, 16)
          if (value > 0x10ffff) fail(backslashLine, backslashColumn, 'invalid escape \\u')
          advance() // closing brace
          decoded += String.fromCodePoint(value)
        } else {
          fail(backslashLine, backslashColumn, `invalid escape \\${e}`)
        }
        continue
      }
      decoded += current()
      advance()
    }
    return { line: startLine, column: startColumn, kind: 'string', text: JSON.stringify(decoded) }
  }

  function scanRawString() {
    const startLine = line
    const startColumn = column
    advance() // 'r'
    advance() // opening quote
    let decoded = ''
    while (true) {
      if (current() === undefined) fail(startLine, startColumn, 'unterminated string')
      if (current() === '"') {
        advance()
        break
      }
      decoded += current()
      advance()
    }
    return { line: startLine, column: startColumn, kind: 'rawstring', text: JSON.stringify(decoded) }
  }

  function scanIdent() {
    const startLine = line
    const startColumn = column
    const startIdx = idx
    advance()
    while (isIdentPart(current())) advance()
    const text = chars.slice(startIdx, idx).join('')
    return { line: startLine, column: startColumn, kind: KEYWORDS.has(text) ? 'keyword' : 'ident', text }
  }

  function scanPunct() {
    const startLine = line
    const startColumn = column
    const two = current() + (peekAt(1) ?? '')
    if (TWO_CHAR_PUNCT.includes(two)) {
      advance()
      advance()
      return { line: startLine, column: startColumn, kind: 'punct', text: two }
    }
    const one = current()
    if (ONE_CHAR_PUNCT.has(one)) {
      advance()
      return { line: startLine, column: startColumn, kind: 'punct', text: one }
    }
    fail(startLine, startColumn, `unexpected character ${one}`)
    return undefined
  }

  const tokens = []
  while (true) {
    skipTrivia()
    if (current() === undefined) break
    const c = current()
    if (c === '"') {
      tokens.push(scanString())
    } else if (c === 'r' && peekAt(1) === '"') {
      tokens.push(scanRawString())
    } else if (isIdentStart(c)) {
      tokens.push(scanIdent())
    } else if (isDecimalDigit(c)) {
      tokens.push(scanNumber())
    } else {
      tokens.push(scanPunct())
    }
  }
  return tokens
}

export { LexError }
"}

